pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        // Make actor the owner by deploying C with actor as smartfix_owner.
        // Since smartfix_owner is set to msg.sender in SmartFix constructor which is inherited,
        // we need a new deployment where actor deploys C.
        vm.prank(actor);
        C c2 = new C();
        address originalOwner = c2.smartfix_owner();
        // The owner must be actor; we assume fuzzer may give actor == originalOwner or not.
        // The operation is to call sudicideAnyone as actor.
        vm.prank(actor);
        bool ok = true;
        try c2.sudicideAnyone() { ok = true; } catch { ok = false; }
        // Rule: if actor is the smartfix_owner, the call must succeed (ok == true).
        // The buggy version always reverts, so ok will be false even when actor == originalOwner.
        assertTrue(actor != originalOwner || ok);
    }
}

