pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));
        bool isOwner = c.smartfix_owner() == caller;
        vm.prank(caller);
        bool reverted;
        try c.sudicideAnyone() { reverted = false; } catch { reverted = true; }
        if (isOwner) {
            assertTrue(!reverted && address(c).code.length == 0);
        } else {
            assertTrue(reverted);
        }
    }
}

